    public void testCoachWorkspaceKeepsPlayerAndPeriodAfterRecreation() throws Exception {
        seed();final String[] owner={null};ui(()->{owner[0]=a.store.player().optString("id");JSONObject coach=profile("QA Continuity Coach","Coach");put(coach,"trackingMode","Power");a.saveRecord("players",coach);put(a.store.data,"selectedPlayerID",coach.optString("id"));a.save();});
        for(String section:new String[]{"roster","schedule","overview","player","capture","records","journal","development","media"}){
            ui(()->{Bundle state=new Bundle();state.putString("screenTable","workspace:"+section);state.putString("screenRecord",owner[0]);state.putInt("screenDays",90);assertTrue(a.restoreScreen(state));});
            recreateScreen();ui(()->{assertEquals("workspace:"+section,a.screenTable);if(!Arrays.asList("roster","schedule","overview").contains(section))assertEquals(owner[0],a.screenRecord);if(section.equals("player"))assertNotNull(findButton(a.root,"Period: 90 days"));});
        }
    }
