    void accessibility(){AccessibilityHierarchyAndroid h=accessibilityHierarchy();List<String> errors=new ArrayList<>();for(AccessibilityHierarchyCheck check:AccessibilityCheckPreset.getAccessibilityHierarchyChecksForPreset(AccessibilityCheckPreset.LATEST))for(AccessibilityHierarchyCheckResult result:check.runCheckOnHierarchy(h))if(result.getType()==AccessibilityCheckResult.AccessibilityCheckResultType.ERROR)errors.add(check.getClass().getSimpleName()+": "+result.getMessage(Locale.UK));assertTrue(errors.toString(),errors.isEmpty());}
