    public void testConcurrentLibraryReadAndAtomicWrite() throws Exception {
        seed();Store writer=new Store(a);java.util.concurrent.atomic.AtomicReference<Throwable> error=new java.util.concurrent.atomic.AtomicReference<>();java.util.concurrent.CountDownLatch start=new java.util.concurrent.CountDownLatch(1);
        Thread save=new Thread(()->{try{start.await();for(int i=0;i<20;i++){put(writer.player(),"profileNotes","QA concurrent snapshot "+i+" "+"x".repeat(4096));writer.save();}}catch(Throwable t){error.set(t);}});
        Thread read=new Thread(()->{try{start.await();for(int i=0;i<40;i++){Store snapshot=new Store(a);assertEquals(1,snapshot.table("players").length());assertEquals("QA Player",playerName(snapshot.player()));assertNull(validate(snapshot.data,false));}}catch(Throwable t){error.set(t);}});
        save.start();read.start();start.countDown();save.join(15000);read.join(15000);assertFalse("Writes complete",save.isAlive());assertFalse("Reads complete",read.isAlive());if(error.get()!=null)throw new AssertionError(error.get());assertTrue(new Store(a).player().optString("profileNotes").startsWith("QA concurrent snapshot 19"));
    }

