        ui(()->{Onboarding.start(a,"Player");put(a.draft,"name","QA Terms player");Onboarding.show(a,a.draft,2);assertFalse(TermsPolicy.accepted(a.draft));findButton(a.root,"Read terms and safe use").performClick();assertEquals("termsOnboarding",a.draftTable);assertEquals("QA Terms player",a.draft.optString("name"));});
